<?php
namespace App\Http\Controllers; use App\Models\Schedule; use App\Models\Order; use App\Models\OrderDetail; use App\Models\Customer; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\Rule;
class OrderController extends Controller {public function index(){$schedules=Schedule::with(['movie','ticketPrice'])->where('show_time','>=',now())->orderBy('show_time')->get();return view('customer.index',compact('schedules'));}
public function store(Request $r){$d=$r->validate(['customer_name'=>'required|string|max:255','customer_email'=>'required|email|max:255','tickets'=>'required|array','tickets.*'=>'nullable|integer|min:0|max:20']);$tickets=array_filter($d['tickets'],fn($q)=>(int)$q>0);if(!$tickets)return back()->withInput()->with('error','Pilih minimal satu tiket.');DB::transaction(function()use($d,$tickets){Customer::updateOrCreate(['email'=>$d['customer_email']],['name'=>$d['customer_name'],'phone'=>'-','address'=>null]);$order=Order::create(['customer_name'=>$d['customer_name'],'customer_email'=>$d['customer_email'],'total_price'=>0,'status'=>'pending']);$total=0;foreach($tickets as $id=>$qty){$s=Schedule::with('ticketPrice')->findOrFail($id);if($s->show_time<now())throw \Illuminate\Validation\ValidationException::withMessages(['tickets'=>'Jadwal sudah lewat.']);$sub=$s->ticketPrice->price*(int)$qty;$total+=$sub;OrderDetail::create(['order_id'=>$order->id,'schedule_id'=>$s->id,'quantity'=>(int)$qty,'subtotal'=>$sub]);}$order->update(['total_price'=>$total]);});return redirect()->route('customer.index')->with('success','Pesanan berhasil dibuat. Silakan simpan nama dan email untuk konfirmasi.');}
public function adminDashboard(Request $r){$query=Order::with(['orderDetails.schedule.movie','orderDetails.schedule.ticketPrice'])->latest();if($r->filled('from'))$query->whereDate('created_at','>=',$r->date('from'));if($r->filled('to'))$query->whereDate('created_at','<=',$r->date('to'));$orders=$query->get();return view('dashboard',compact('orders'));}
public function updateStatus(Request $r,$id){$d=$r->validate(['status'=>['required',Rule::in(['pending','completed','cancelled'])]]);Order::findOrFail($id)->update($d);return back()->with('success','Status pesanan diperbarui.');}}
